import { useId } from "react";
import { cn } from "@/lib/utils";

/**
 * Vettly logo. Geometry matches public/brand/*.svg (generated by scripts/generate-brand.mjs);
 * change both together. Renders inline so it inherits layout and needs no network request.
 */
const LEFT = "M6 6 H33 L54 62 L44 84 Z";
const RIGHT = "M38 84 L77 6 H96 L53 84 Z";

export function LogoMark({
  className,
  tone = "color",
  title,
}: {
  className?: string;
  tone?: "color" | "mono";
  title?: string;
}) {
  const id = useId().replace(/:/g, "");
  return (
    <svg
      viewBox="0 0 100 88"
      className={cn("h-7 w-auto shrink-0", className)}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
    >
      {tone === "color" ? (
        <>
          <defs>
            <linearGradient id={`${id}l`} x1="6" y1="6" x2="54" y2="84" gradientUnits="userSpaceOnUse">
              <stop offset="0" stopColor="#6366F1" />
              <stop offset="1" stopColor="#8B5CF6" />
            </linearGradient>
            <linearGradient id={`${id}r`} x1="47" y1="84" x2="92" y2="6" gradientUnits="userSpaceOnUse">
              <stop offset="0" stopColor="#3B82F6" />
              <stop offset="1" stopColor="#22D3EE" />
            </linearGradient>
          </defs>
          <path d={LEFT} fill={`url(#${id}l)`} stroke={`url(#${id}l)`} strokeWidth="5" strokeLinejoin="round" />
          <path d={RIGHT} fill={`url(#${id}r)`} stroke={`url(#${id}r)`} strokeWidth="5" strokeLinejoin="round" />
        </>
      ) : (
        <>
          <defs>
            <mask id={`${id}m`} maskUnits="userSpaceOnUse" x="0" y="0" width="100" height="88">
              <rect width="100" height="88" fill="#fff" />
              <path d={RIGHT} fill="#000" stroke="#000" strokeWidth="12" strokeLinejoin="round" />
            </mask>
          </defs>
          <path d={LEFT} fill="currentColor" stroke="currentColor" strokeWidth="5" strokeLinejoin="round" mask={`url(#${id}m)`} />
          <path d={RIGHT} fill="currentColor" stroke="currentColor" strokeWidth="5" strokeLinejoin="round" />
        </>
      )}
    </svg>
  );
}

/** Horizontal lockup. The wordmark is set in Plus Jakarta Sans ExtraBold (loaded app-wide). */
export function Logo({
  className,
  onDark,
  tone = "color",
  markClassName,
}: {
  className?: string;
  onDark?: boolean;
  tone?: "color" | "mono";
  markClassName?: string;
}) {
  return (
    <span className={cn("inline-flex items-center gap-2", onDark ? "text-white" : "text-ink-900", className)}>
      <LogoMark tone={tone} className={markClassName} />
      <span className="text-[1.375rem] leading-none font-extrabold tracking-[-0.025em]">Vettly</span>
    </span>
  );
}
